    String format(Map<String,String> fields){StringBuilder b=new StringBuilder();for(Map.Entry<String,String> e:fields.entrySet())b.append(e.getKey()).append(":\n").append(e.getValue()).append("\n\n");return b.toString();}File txt(String name,String content)throws Exception{File out=Files.unique(outputDir,name);try(OutputStream o=new FileOutputStream(out)){o.write(content.getBytes(Files.UTF8));}return out;}
