    void rebuild(){if(qrTool!=null){qrTool.release();qrTool=null;}if(qrCamera!=null)qrCamera.close();toolbar.findViewWithTag("navigation").setContentDescription(t("打开功能菜单","Open navigation"));((Button)progressBox.findViewWithTag("cancel")).setText(t("取消任务","Cancel task"));message(t("全部在本机处理","All processing stays on this device"));cancelPreview();for(Widgets.Preview p:previews){p.ticket++;ui.removeCallbacks(p.dispatchPreview);p.previewQueued=false;p.pending=null;p.set(null);}previews.clear();queues.clear();saveModes.clear();if(editor!=null&&editor.getParent()!=null)((ViewGroup)editor.getParent()).removeView(editor);for(int i=0;i<pages.length;i++){if(pages[i]!=null)layout.removeView(pages[i]);pages[i]=null;}showPage(page);}
    public void onConfigurationChanged(android.content.res.Configuration c){super.onConfigurationChanged(c);closeDrawer();for(ScrollView p:pages)if(p!=null)p.requestLayout();root.requestApplyInsets();}
    public void onBackPressed(){if(overlay!=null)closeDrawer();else if(busy)new AlertDialog.Builder(this).setMessage(t("取消当前任务？","Cancel current task?")).setPositiveButton(t("取消任务","Cancel task"),(d,w)->{if(active!=null)active.cancelled=true;}).setNegativeButton(t("继续处理","Keep processing"),null).show();else super.onBackPressed();}
