    void releaseHiddenPreviews(){for(Widgets.Preview p:previews)if(!isVisible(p)){p.ticket++;ui.removeCallbacks(p.dispatchPreview);p.previewQueued=false;p.pending=null;p.set(null);}}
    public void onTrimMemory(int level){super.onTrimMemory(level);if(level>=TRIM_MEMORY_RUNNING_LOW){cancelPreview();releaseHiddenPreviews();}}
    boolean isVisible(View v){return v.isShown();}
    protected void onDestroy(){destroyed=true;if(aiController!=null)aiController.close();if(qrCamera!=null)qrCamera.close();if(qrTool!=null)qrTool.release();cancelPreview();if(dualPreviewJob!=null)dualPreviewJob.cancelled=true;if(dualRestorePreviewJob!=null)dualRestorePreviewJob.cancelled=true;if(active!=null)active.cancelled=true;worker.execute(()->{if(editor!=null)editor.release();});worker.shutdown();for(Widgets.Preview p:previews)p.set(null);super.onDestroy();}
